refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     min lance désormais une ValueError en cas d'échec ;
     précédemment, &false; était renvoyé et une erreur E_WARNING était émise.




    8.0.0

     Comme les 
     comparaisons entre les chaînes et les nombres ont été changées,
     min ne retourne plus une valeur différente
     basée sur l'ordre des arguments dans ces cas là.

  &reftitle.examples;



    Exemple avec min


<?php
echo min(2, 3, 1, 6, 7), PHP_EOL;  // 1
echo min(array(2, 4, 5)), PHP_EOL; // 2

// 'hello' est une chaîne non numérique, donc -1 est converti en la chaîne "-1"
// et les valeurs sont comparées comme des chaînes : "-1" est inférieur à "hello"
echo min('hello', -1), PHP_EOL;    // -1

// Avec plusieurs tableaux de différentes tailles, min retourne le plus court
$val = min(array(2, 2, 2), array(1, 1, 1, 1)); // array(2, 2, 2)
var_dump($val);

// Plusieurs tableaux de même taille sont comparés depuis la gauche vers la droite,
// aussi, dans notre exemple : 2 == 2, mais 4 < 5
$val = min(array(2, 4, 8), array(2, 5, 1)); // array(2, 4, 8)
var_dump($val);

// Si un tableau et un non-tableau sont fournis, le tableau ne sera jamais retourné
// car les comparaisons traitent les tableaux comme plus grand que n'importe quelle valeur
// Parmi les valeurs restantes, 42 est converti en la chaîne "42" lorsqu'il est
// comparé à la chaîne non numérique 'string', et "42" est inférieur à "string"
$val = min('string', array(2, 5, 7), 42);   // 42
var_dump($val);

// Si un argument vaut NULL ou vaut un booléen, il sera comparé avec
// d'autres valeurs en utilisant les règles FALSE < TRUE et NULL == FALSE suivant
// les autres types fournis. Dans l'exemple ci-dessous, à la fois -10 et 10 sont traités
// comme valant TRUE dans la comparaison
$val = min(-10, FALSE, 10); // FALSE
var_dump($val);

$val = min(-10, NULL, 10);  // NULL
var_dump($val);

// D'un autre côté, 0 est traité comme valant FALSE, aussi, il est "plus petit que" TRUE
$val = min(0, TRUE); // 0
var_dump($val);
?>
